(function(){try{var a=typeof window<"u"?window:typeof global<"u"?global:typeof globalThis<"u"?globalThis:typeof self<"u"?self:{},n=new a.Error().stack;n&&(a._sentryDebugIds=a._sentryDebugIds||{},a._sentryDebugIds[n]="b3c8aba0-8f2b-45c5-839d-c1e5d17cc4cd",a._sentryDebugIdIdentifier="sentry-dbid-b3c8aba0-8f2b-45c5-839d-c1e5d17cc4cd")}catch{}})();var e="Kod Tatakelakuan Komuniti",i={p1:"Kita semua menggemari muzik! Seperti mana-mana komuniti, kami mempunyai kod tatakelakuan untuk mengekalkan harmoni dan suasana positif, serta memastikan semua orang berasa selesa di sini. Mari bina persekitaran mesra yang mengilhamkan kita untuk berkarya."},k={p1:"Prinsip kebersamaan:",p2:"Hormat",p3:"Persaudaraan",p4:"Kesaksamaan"},m={p1:"Perilaku yang diharapkan:",p2:"Layan semua ahli dengan hormat.",p3:"Maklum balas yang membina amat dialu-alukan.",p4:"Segalanya tentang muzik, jadi pastikan komen dan kandungan kita kekal berkaitan muzik sahaja.",p5:"Layan orang lain sebagaimana anda mahu dilayan."},t={p1:"Perilaku yang tidak boleh diterima (kami boleh memadam akaun anda tanpa amaran):",p2:"Melayan sesama pencipta dengan tidak hormat atau menyinggung perasaan.",p3:"Spam.",p4:"Berkongsi kandungan berunsur seksual.",p5:"Membuat komen yang bertujuan merendah-rendahkan, menyinggung, atau mengganggu mana-mana ahli komuniti."},s={p1:"Tindakan umum:"},d={p1:"Sebab untuk disekat serta-merta:",p2:"Berkongsi apa-apa jenis kandungan berunsur seksual (imej, komen, dan sebagainya).",p3:"Berkongsi kandungan atau membuat komen yang menggalakkan keganasan, rasisme, xenofobia, homofobia, seksisme, dan sebagainya.",p4:"Menghantar spam kepada orang lain."},u={p1:"Jenis-jenis tingkah laku lain yang tidak boleh diterima:",p2:"Menghina atau menyiarkan komen yang merendah-rendahkan mana-mana ahli komuniti:",p3:"Kali pertama: kami akan menyahaktifkan keupayaan untuk membuat komen sehingga diberitahu kelak.",p4:"Kali ke-2: kami akan menyekat fungsi komen secara kekal, atau memadam akaun anda.",p5:"Spam di saluran sokongan:",p6:"Pasukan sokongan kami sentiasa bersedia membantu anda asalkan anda menulis kepada kami dengan sopan dan hanya mengenai platform kami. Sikap tidak menghormati atau bersifat spam tidak dialu-alukan dan boleh mengakibatkan akaun anda dipadam."},r={p1:"Apakah yang dianggap sebagai komen tidak sopan?",p2:"Jenis komen ini lazimnya tidak berkaitan, tidak sesuai, memudaratkan, atau sekadar mengganggu. Penulisnya tidak menulis dengan niat baik, dan bertujuan membuat orang lain berasa buruk atau terhina.",p3:"Jika anda tidak pasti sama ada komen anda tidak sopan atau tidak, elakkan menyiarkannya dan cari cara yang beradab serta penuh hormat untuk menyampaikan pandangan anda."},p={title:e,s1:i,s2:k,s3:m,s4:t,s5:s,s6:d,s7:u,s8:r};export{p as default,i as s1,k as s2,m as s3,t as s4,s as s5,d as s6,u as s7,r as s8,e as title};

